<span class="line"><span style="--shiki-light:#AB5959;--shiki-dark:#CB7676">    struct</span><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE"> sensor_cfg cfg</span><span style="--shiki-light:#999999;--shiki-dark:#666666">;</span></span>
